-        reduce_fn: Callable = lambda i: np.max(i, axis=-1),
-        obstacle_map: Optional["ObstacleMap"] = None,  # type: ignore # noqa: F821
-    ) -> np.ndarray:
-        """Return an image representation of the map"""
