-    x = [0, 10, 10, 0]
-    y = [0, 0, 10, 10]
-    angles = [0, np.pi / 2, np.pi, 3 * np.pi / 2]
-
-    points = np.stack((x, y), axis=1)
-
-    for pt, angle in zip(points, angles):
