-        "depth",
-        "semantic",
-    )
-    semantic_key: str = "semantic"
-
-
-cs = ConfigStore.instance()
-
-cs.store(
-    package="habitat_baselines.rl.policy.obs_transforms.resize",
-    group="habitat_baselines/rl/policy/obs_transforms",
-    name="resize",
