-
-    def __init__(
-        self,
-        camera_height: float,
-        min_depth: float,
-        max_depth: float,
-        camera_fov: float,
-        image_width: int,
-        dataset_type: str = "hm3d",
-        *args: Any,
-        **kwargs: Any,
