-        # Draw unnavigable areas in gray
-        vis_img[self._navigable_map == 0] = self.radius_padding_color
-        # Draw obstacles in black
-        vis_img[self._map == 1] = (0, 0, 0)
-        # Draw frontiers in blue (200, 0, 0)
-        for frontier in self._frontiers_px:
