-            "nav_depth": observations["depth"],  # for pointnav
-            "robot_xy": robot_xy,
-            "robot_heading": camera_yaw,
-            "object_map_rgbd": [
-                (
-                    rgb,
-                    depth,
-                    tf_camera_to_episodic,
-                    self._min_depth,
-                    self._max_depth,
-                    self._fx,
-                    self._fy,
-                )
-            ],
-            "value_map_rgbd": [
-                (
-                    rgb,
-                    depth,
-                    tf_camera_to_episodic,
-                    self._min_depth,
-                    self._max_depth,
-                    self._camera_fov,
-                )
-            ],
-            "habitat_start_yaw": observations["heading"][0].item(),
-        }
