-    lines = []
-    flattened_info = flatten_dict(info)
-    for k, v in flattened_info.items():
-        if isinstance(v, str):
-            lines.append(f"{k}: {v}")
-        else:
-            try:
-                lines.append(f"{k}: {v:.2f}")
-            except TypeError:
-                pass
-    if additional is not None:
-        lines.extend(additional)
-
-    frame = overlay_text_to_image(frame, lines, font_size=0.25)
