-
-        if RECORDING:
-            idx = len(glob.glob(osp.join(RECORDING_DIR, "*.png")))
-            img_path = osp.join(RECORDING_DIR, f"{idx:04d}.png")
-            cv2.imwrite(img_path, (depth * 255).astype(np.uint8))
-            with open(JSON_PATH, "r") as f:
