-                (self._depth_image_shape[0], self._depth_image_shape[1]),
-                channels_last=True,
-                interpolation_mode="area",
-            ),
-            "pointgoal_with_gps_compass": rho_theta_tensor,
-        }
-        self._policy_info["rho_theta"] = np.array([rho, theta])
