-        st = time.time()
-        action = policy.get_action(observations, mask, deterministic=True)
-        print(f"get_action took {time.time() - st:.2f} seconds")
-        mask = torch.ones_like(mask)
-        if done:
-            print("Episode finished because done is True")
-            break
