-        use_vqa=False,
-        vqa_prompt="Is this ",
-        coco_threshold=0.8,
-        non_coco_threshold=0.4,
-        camera_height=0.88,
-        min_depth=0.5,
-        max_depth=5.0,
-        camera_fov=79,
-        image_width=640,
-        visualize=True,
