-        )
-    else:
-        policy_cls = SemExpITMPolicyV2
-
-    policy = policy_cls(**policy_kwargs)  # type: ignore
-
-    torch.set_num_threads(1)
-    envs = make_vec_envs(args)
-    obs, infos = envs.reset()
-    ep_id, scene_id, target_object = "", "", ""
-    for ep_num in range(num_episodes):
