-        for step in range(args.max_episode_length):
-            if step == 0:
-                masks = torch.zeros(1, 1, device=obs.device)
-                ep_id, scene_id = infos[0]["episode_id"], infos[0]["scene_id"]
-                target_object = infos[0]["goal_name"]
