-            image = str_to_image(payload["image"])
-            return {"response": self.detect(image, payload["phrase"]).to_json()}
-
-    fiber = FIBERServer()
-    print("Model loaded!")
-    print(f"Hosting on port {args.port}...")
-    host_model(fiber, name="fiber", port=args.port)
